// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;

    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(address tokenOwner, uint256 tokens) public {
        RecordToken token = new RecordToken();
        vm.assume(tokenOwner != address(token));
        bool ok = c.transferAnyERC20Token(address(token), tokenOwner, tokens);
        // Rule: for any recipient != the token itself, the call forwards the tokens
        // to that recipient and returns the token's decision (true here).
        assertTrue(ok);
    }
}

contract RecordToken {
    function transfer(address to, uint256) public returns (bool) {
        return to != address(this);
    }
}
